const NUM_RIBBONS = 6;
const STEPS = 60;
let cacheX = new Float32Array(NUM_RIBBONS * STEPS);
let cacheY = new Float32Array(NUM_RIBBONS * STEPS);
let heads = [];
let params = { a: 1.5, b: -1.8, c: 1.6, d: 0.9 };
let baseT = 0;

const eqMap = {
  "Pure Clifford Fold": 0,
  "Clifford Hybrid": 1,
  "De Jong Balanced": 2,
  "De Jong Asymmetric": 3,
  "Svensson Swirl": 4,
  "Svensson Turbulent": 5
};

const chaosMap = {
  "Gentle Harmonic Drift": 0.0005,
  "Slow Tidal Unspooling": 0.0015,
  "Brisk Chaotic Weave": 0.003,
  "Restless Vortex": 0.006,
  "Turbulent Whiplash": 0.01,
  "Electric Jitter Storm": 0.015
};

const symMap = {
  "Single Asymmetric Knot": 1,
  "Bilateral Mirror": 2,
  "Trifold Rosette": 3,
  "Quad Mandala": 4,
  "Hexagonal Bloom": 6,
  "Octagonal Lotus": 8
};

const thickMap = {
  "Gossamer Filament": 0.7,
  "Fine Silk Thread": 0.8,
  "Translucent Ribbon": 1.5,
  "Broad Satin Band": 3.0,
  "Dense Velvet Strip": 5.0,
  "Heavy Opaque Beam": 8.0
};

const palMap = {
  "Smoldering Ember": ["#550000", "#990000", "#dd3300", "#ff7700", "#ffcc00"],
  "Solar Flare": ["#990000", "#ee4400", "#ff9900", "#ffee00", "#ffffff"],
  "Neon Synthwave": ["#330055", "#9900ff", "#ff0099", "#00ffff", "#ffffff"],
  "Bioluminescent Coral": ["#003344", "#009977", "#00ffbb", "#ff00bb", "#ffccff"],
  "Deep Abyssal Blue": ["#000022", "#000055", "#003399", "#0077ff", "#00ddff"],
  "Spectral Prismatic": ["#ff0000", "#ffbb00", "#00ff00", "#0099ff", "#dd00ff"]
};

p.setup = function() {
  p.createCanvas(800, 800);
  p.background(0);
  for (let i = 0; i < NUM_RIBBONS; i++) {
    heads.push({ x: p.random(-2, 2), y: p.random(-2, 2) });
  }
};

p.draw = function() {
  const eqName = p.getSynthVar("equation_family") || "Pure Clifford Fold";
  const chaosName = p.getSynthVar("chaos_degree") || "Gentle Harmonic Drift";
  const symName = p.getSynthVar("symmetry_folds") || "Single Asymmetric Knot";
  const thickName = p.getSynthVar("ribbon_thickness") || "Gossamer Filament";
  const palName = p.getSynthVar("velocity_palette") || "Smoldering Ember";

  const eqType = eqMap[eqName] || 0;
  const chaosSpeed = chaosMap[chaosName] || 0.0005;
  const folds = symMap[symName] || 1;
  const thickness = thickMap[thickName] || 0.7;
  const colors = palMap[palName] || palMap["Smoldering Ember"];

  let jitter = 0;
  if (chaosName === "Electric Jitter Storm" && p.frameCount % 20 < 4) {
    jitter = p.random(0.5, 2.0);
  } else if (chaosName === "Turbulent Whiplash") {
    jitter = p.sin(p.frameCount * 0.5) * 0.2;
  }

  baseT += chaosSpeed;
  params.a = p.sin(baseT * 1.1) * 2.0 + jitter;
  params.b = p.cos(baseT * 1.3) * 2.0 - jitter;
  params.c = p.sin(baseT * 0.7) * 2.0 + jitter;
  params.d = p.cos(baseT * 0.9) * 2.0 - jitter;

  for (let r = 0; r < NUM_RIBBONS; r++) {
    let px = heads[r].x;
    let py = heads[r].y;
    let offset = r * STEPS;

    for (let s = 0; s < STEPS; s++) {
      let vx, vy;
      if (eqType === 0) {
        vx = p.sin(params.a * py) + params.c * p.cos(params.a * px);
        vy = p.sin(params.b * px) + params.d * p.cos(params.b * py);
      } else if (eqType === 1) {
        vx = p.sin(params.a * py) - params.c * p.cos(params.a * px);
        vy = p.sin(params.b * px) - params.d * p.cos(params.b * py);
      } else if (eqType === 2) {
        vx = p.sin(params.a * py) - p.cos(params.b * px);
        vy = p.sin(params.c * px) - p.cos(params.d * py);
      } else if (eqType === 3) {
        vx = p.sin(params.b * py) - p.cos(params.c * px);
        vy = p.sin(params.d * px) - p.cos(params.a * py);
      } else if (eqType === 4) {
        vx = p.sin(params.a * py) + params.c * p.sin(params.a * px);
        vy = p.cos(params.b * px) + params.d * p.cos(params.b * py);
      } else {
        vx = p.sin(params.a * py) - params.c * p.sin(params.b * px);
        vy = p.cos(params.d * px) + params.b * p.cos(params.c * py);
      }

      let nx = px + vx * 0.08;
      let ny = py + vy * 0.08;

      let velSq = vx * vx + vy * vy;
      if (velSq < 0.0001 || p.abs(nx) > 6 || p.abs(ny) > 6 || isNaN(nx) || isNaN(ny)) {
        nx = p.random(-2, 2);
        ny = p.random(-2, 2);
      }

      cacheX[offset + s] = nx;
      cacheY[offset + s] = ny;
      px = nx;
      py = ny;
    }
    heads[r].x = px;
    heads[r].y = py;
  }

  const ctx = p.drawingContext;
  let fadeAlpha = (thickness < 1.0 && folds <= 2) ? 0.015 : 0.04;
  ctx.fillStyle = `rgba(0, 0, 0, ${fadeAlpha})`;
  ctx.fillRect(0, 0, p.width, p.height);

  ctx.lineCap = "round";
  ctx.lineJoin = "round";
  ctx.lineWidth = thickness;

  const ribbonAlpha = p.floor(p.map(thickness, 0.7, 8.0, 255, 60)).toString(16).padStart(2, '0');

  const cx = p.width / 2;
  const cy = p.height / 2;
  const scale = p.width / 4.2;

  for (let f = 0; f < folds; f++) {
    ctx.save();
    ctx.translate(cx, cy);
    ctx.rotate((p.TWO_PI / folds) * f);

    for (let r = 0; r < NUM_RIBBONS; r++) {
      let offset = r * STEPS;
      ctx.beginPath();
      ctx.strokeStyle = colors[r % colors.length] + ribbonAlpha;
      ctx.moveTo(cacheX[offset] * scale, cacheY[offset] * scale);

      for (let s = 1; s < STEPS; s++) {
        ctx.lineTo(cacheX[offset + s] * scale, cacheY[offset + s] * scale);
      }
      ctx.stroke();
    }
    ctx.restore();
  }
};
